mapper.sql:
WHERE p.deleted_at IS NULL
  AND p.status = 'PUBLISHED'

    AND m.publication_year = #{year}


    AND m.publication_month = #{month}


    AND m.document_type = #{documentType}


    AND m.publication_category_id = #{categoryId}


    AND (p.title ILIKE '%' || #{keyword} || '%'
         OR m.publisher ILIKE '%' || #{keyword} || '%')

mapper.select:
SELECT
FROM bbs_post_publication_meta m JOIN bbs_post p ON p.id = m.post_id LEFT JOIN publication_category c ON c.id = m.publication_category_id
ORDER BY m.publication_year DESC, m.publication_month DESC NULLS LAST, p.created_at DESC LIMIT #{size} OFFSET #{offset}

mapper.insert:
INSERT INTO bbs_post_publication_meta ( post_id, publication_year, publication_month, document_type, publication_category_id, isbn, publisher, metadata ) VALUES ( #{postId}, #{req.publicationYear}, #{req.publicationMonth}, #{req.documentType}, #{req.publicationCategoryId}, #{req.isbn}, #{req.publisher},
#{req.metadata}::jsonb NULL
)
